css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; display: grid; place-items: center; }
.loader span { position: absolute; width: 40%; height: 58%; background: radial-gradient(circle at 50% 38%, color-mix(in srgb, #fff 25%, var(--accent-2)), var(--accent)); border-radius: 50% 50% 50% 50% / 62% 62% 38% 38%; }
.loader span:nth-child(1) { left: 8%; transform-origin: right center; animation: flap-l calc(var(--loader-speed) * .6) ease-in-out infinite; }
.loader span:nth-child(2) { right: 8%; transform-origin: left center; animation: flap-r calc(var(--loader-speed) * .6) ease-in-out infinite; }
.loader::after { content: ''; position: absolute; left: 50%; top: 22%; width: calc(var(--loader-size) * .045); height: 56%; margin-left: calc(var(--loader-size) * -.0225); background: #1e293b; border-radius: 4px; z-index: 2; }
@keyframes flap-l { 0%, 100% { transform: perspective(220px) rotateY(0deg); } 50% { transform: perspective(220px) rotateY(72deg); } }
@keyframes flap-r { 0%, 100% { transform: perspective(220px) rotateY(0deg); } 50% { transform: perspective(220px) rotateY(-72deg); } }
